package dump

import (
	"bytes"
	"strings"
	"testing"
)

type node struct {
	Name  string
	Child *node
	Tags  map[string]int
}

func TestSdumpNestedValue(t *testing.T) {
	root := &node{Name: "root", Tags: map[string]int{"b": 2, "a": 1}}
	root.Child = &node{Name: "leaf"}

	got := Sdump(root)

	for _, want := range []string{"(*dump.node)", `Name: "root"`, `Name: "leaf"`, "a: 1", "b: 2"} {
		if !strings.Contains(got, want) {
			t.Fatalf("Sdump() missing %q in:\n%s", want, got)
		}
	}
	if strings.Contains(got, "0x") {
		t.Fatalf("pointer addresses should be suppressed, got:\n%s", got)
	}
}

func TestSortKeysIsDeterministic(t *testing.T) {
	m := map[string]int{"c": 3, "a": 1, "b": 2}

	got := Sdump(m)

	if strings.Index(got, "a: 1") > strings.Index(got, "b: 2") {
		t.Fatalf("map keys are not sorted:\n%s", got)
	}
}

func TestDepthStopsRecursion(t *testing.T) {
	n := &node{Name: "self"}
	n.Child = n

	got := Depth(2).Sdump(n)

	if !strings.Contains(got, "...") {
		t.Fatalf("expected elision marker when depth is exceeded, got:\n%s", got)
	}
}

func TestFdumpWritesToWriter(t *testing.T) {
	var buf bytes.Buffer

	Fdump(&buf, map[string]string{"k": "v"})

	if buf.Len() == 0 {
		t.Fatal("Fdump wrote nothing")
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/example/debugtool/dump"
)

type request struct {
	ID       int
	Method   string
	Headers  map[string]string
	Params   []any
	Canceled bool
}

func sample() any {
	r := &request{
		ID:     42,
		Method: "debug.inspect",
		Headers: map[string]string{
			"Accept":        "application/json",
			"Authorization": "Bearer <redacted>",
		},
		Params: []any{1, "two", map[string]bool{"nested": true}},
	}
	return map[string]any{"request": r, "count": 3}
}

func main() {
	dec := json.NewDecoder(os.Stdin)

	var v any
	if err := dec.Decode(&v); err != nil {
		if err == io.EOF {
			dump.Dump(sample())
			return
		}
		fmt.Fprintln(os.Stderr, "godump:", err)
		os.Exit(1)
	}

	dump.Dump(v)
}

